style.css:
@-moz-document domain("roblox.com") {
body, html, .container-main, .content {
    background: #121212 !important; color: #eee !important;
  }
  .navbar, .footer, .navigation-container {
    background: #1f1f1f !important;
  }
  .btn-primary, .btn-secondary {
    background: #333 !important; color: #fff !important;
  }
  .abp, .ad, .ads-container, [id*="ad"], [class*="Ad"],
  .premium-upsell-container, .upgrade-now-banner,
  .game-carousel, .home-friends-carousel {
    display: none !important;
  }
}
